from agentfox.io.errors import handle_cli_errors

@handle_cli_errors
def raises_exception():
    raise ValueError("caught")

@handle_cli_errors
def raises_system_exit():
    raise SystemExit(0)

@handle_cli_errors
def raises_keyboard_interrupt():
    raise KeyboardInterrupt()

# ValueError is caught (no exception propagates from handle_cli_errors)
try:
    raises_exception()
except SystemExit:
    pass  # expected sys.exit(1) from handler
except ValueError:
    assert False, "ValueError should be caught"

# SystemExit propagates
try:
    raises_system_exit()
except SystemExit as e:
    assert e.code == 0

# KeyboardInterrupt propagates
try:
    raises_keyboard_interrupt()
except KeyboardInterrupt:
    pass  # expected

from click.testing import CliRunner
from agentfox.io import AgentFoxGroup
import click

@click.group(cls=AgentFoxGroup)
def cli(): pass

@cli.command()
def fail():
    raise ValueError("oops")

@cli.command()
def succeed():
    raise SystemExit(0)

runner = CliRunner()
result_fail = runner.invoke(cli, ["fail"])
assert result_fail.exit_code == 1

result_succeed = runner.invoke(cli, ["succeed"])
assert result_succeed.exit_code == 0

import threading
from agentfox.io import StatusSpinner
errors = []
with mock_non_tty():
    with StatusSpinner("msg", quiet=False, theme=None) as s:
        def do_update():
            try:
                for i in range(10):
                    s.update(f"step {i}")
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=do_update) for _ in range(5)]
        for t in threads: t.start()
        for t in threads: t.join()

assert len(errors) == 0

