import click
import logging
from agentfox.io import common_options

@click.group()
@click.option("--json", is_flag=True)
@common_options
def cli(json): pass

# 1. Count json params — MUST be exactly 1, not 0 and not 2
json_params = [p for p in cli.params if p.name == "json"]
assert len(json_params) == 1, f"expected exactly 1 json param, got {len(json_params)}"

# 2. Verify a debug-level warning was logged about the name collision
# Use pytest caplog fixture to capture log records
with caplog.at_level(logging.DEBUG):
    @click.group()
    @click.option("--json", is_flag=True)
    @common_options
    def cli2(json): pass

debug_records = [r for r in caplog.records if r.levelno == logging.DEBUG]
assert any("json" in r.message.lower() and ("skip" in r.message.lower() or "conflict" in r.message.lower() or "collision" in r.message.lower() or "already" in r.message.lower()) for r in debug_records), "expected debug log about json flag collision"

