from click.testing import CliRunner
from agentfox.io import AgentFoxGroup, common_options
import click

@click.group(cls=AgentFoxGroup)
@common_options
def cli(): pass

captured = []
@cli.command()
@click.pass_context
def sub(ctx):
    captured.append(ctx.obj["output"])

for bad_val in ["true", "yes", "on", "0", ""]:
    captured.clear()
    runner = CliRunner(env={"AF_AGENT": bad_val})
    runner.invoke(cli, ["sub"])
    assert captured[0].json_mode == False, f"AF_AGENT={bad_val!r} wrongly activated json_mode"
    assert captured[0].quiet == False, f"AF_AGENT={bad_val!r} wrongly activated quiet"
